return $input.all().map(item => {
  const data = item.json;

  // Приводимо рейтинг до числа
  const rating = parseFloat(data.rating || 0);

  // Визначаємо рівень бізнес-критичності
  let priority = "ℹ️ МЕДІУМ (МОНІТОРИНГ)";
  if (rating <= 2.5) {
    priority = "🚨 КРИТИЧНИЙ ДЕФЕКТ (ТЕРМІНОВО ЗНЯТИ З ПРОДАЖУ)";
  } else if (rating <= 3.2) {
    priority = "⚠️ ВИСОКИЙ ПРІОРИТЕТ (ПЕРЕВІРИТИ ПАРТІЮ)";
  }

  // Форматуємо масив відгуків через нову лінію
  const reviewsList = data.reviews || [];
  const reviewsText = reviewsList.map(r => `- ${r}`).join('\n');

  // Повертаємо новий чистий об'єкт
  return {
    json: {
      product_name: data.product_name,
      product_link: data.product_link,
      price: data.price,
      rating: rating,
      reviews_text: reviewsText,
      priority: priority
    }
  };
});

return $input.all().map(item => {
  const data = item.json;

  // Імітуємо розумні висновки LLM залежно від товару
  let defect = "Груба плівка капсули, що не розчиняється у воді";
  let action = "Тимчасово вилучити партію з полиць, надіслати претензію постачальнику.";

  if (data.product_name.includes("посуду")) {
    defect = "Занадто рідка консистенція, великі репутаційні ризики";
    action = "Провести аудит технологів виробника або замінити бренд.";
  }

  return {
    json: {
      ...data,
      ai_analysis: {
        defect: defect,
        recommended_action: action
      }
    }
  };
});
